/* COMPARE devices */
// Hai vùng cắt cạnh cứng (coral region split, dọc cho 9:16). static=true -> làm móc, đủ nghĩa ở khung 0.
HFS.device("split", {
  meta: { purpose: "compare", framing: "stacked-split", axis: "mask", circle: 0, energy: "M" },
  css: `.sp-a,.sp-b{position:absolute;left:0;right:0}
        .sp-a{top:250px;height:610px}.sp-b{top:860px;height:600px;background:var(--accent2);color:var(--on-accent2)}
        .sp-lab{position:absolute;left:108px;font-size:30px}.sp-a .sp-lab{top:90px;color:var(--accent)}.sp-b .sp-lab{top:70px;color:var(--glow)}
        .sp-val{position:absolute;left:100px;right:110px;font-size:160px}.sp-a .sp-val{top:140px}.sp-b .sp-val{top:120px}
        .sp-num{position:absolute;left:104px;font-size:220px;line-height:1;transform:rotate(-5deg);transform-origin:0 100%;white-space:nowrap}
        .sp-a .sp-num{top:350px;color:var(--accent)}.sp-b .sp-num{top:330px;color:var(--glow)}
        .sp-rule{position:absolute;left:0;right:0;top:856px;height:8px;background:var(--accent);transform-origin:0 50%}`,
  cssW: `.sp-a,.sp-b{position:absolute;top:0;bottom:0}
        .sp-a{left:0;width:960px}.sp-b{left:960px;right:0;background:var(--accent2);color:var(--on-accent2)}
        .sp-lab{position:absolute;left:150px;font-size:28px}.sp-a .sp-lab{top:190px;color:var(--accent)}.sp-b .sp-lab{top:190px;left:110px;color:var(--glow)}
        .sp-val{position:absolute;left:150px;right:70px;font-size:96px}.sp-a .sp-val{top:240px}.sp-b .sp-val{top:240px;left:110px;right:150px}
        .sp-num{position:absolute;left:150px;font-size:200px;line-height:1;transform:rotate(-5deg);transform-origin:0 100%;white-space:nowrap}
        .sp-a .sp-num{top:520px;color:var(--accent)}.sp-b .sp-num{top:520px;left:110px;color:var(--glow)}
        .sp-rule{position:absolute;left:956px;width:8px;top:0;bottom:0;background:var(--accent);transform-origin:50% 0}`,
  build(c, s, st) {
    const A = c.el("div", "sp-a", null, st), B = c.el("div", "sp-b", null, st), rule = c.el("div", "sp-rule", null, st);
    [A, B].forEach((x) => x.setAttribute("data-layout-allow-overlap", ""));
    const mk = (box, p) => { c.el("div", "sp-lab mono", c.esc(p.lab || ""), box); const v = c.el("div", "sp-val heavy", null, box);
      const ws = c.words(v, p.val); if (p.num) c.el("div", "sp-num disp", c.esc(p.num), box); return ws; };
    return { A, B, rule, wa: mk(A, s.a), wb: mk(B, s.b) };
  },
  enter(c, h, t0, s) {
    if (s.static) return;
    const ta = Math.max(t0 + .05, c.t(s.a.at, t0)), tb = Math.max(t0 + .6, c.t(s.b.at, t0 + 2));
    c.waterfall(h.wa, c.spread(ta, ta + .3, h.wa.length));
    const ax = c.L.wide ? "scaleY" : "scaleX";      // khổ ngang: hai cột trái/phải, vạch chia dọc
    c.tl.set(h.rule, { [ax]: 0 }, 0); c.tl.to(h.rule, { [ax]: 1, duration: c.S(.5), ease: c.E.entry }, tb - .45);
    c.tl.set(h.B, { clipPath: c.L.wide ? "inset(0 0 0 100%)" : "inset(100% 0 0 0)" }, 0);
    c.tl.to(h.B, { clipPath: c.L.wide ? "inset(0 0 0 0%)" : "inset(0% 0 0 0)", duration: c.S(.45), ease: "power4.out" }, tb - .3);
    c.waterfall(h.wb, c.spread(tb, tb + .3, h.wb.length), { y: 60 });
  },
});

// Ngộ nhận bị gạch -> sự thật đến bằng inverse zoom (H6 / myth-strike). BUD: glitch tắt (theme), không crash.
HFS.device("myth_strike", {
  meta: { purpose: "compare", framing: "center-hero", axis: "X", circle: 0, energy: "H" },
  css: `.ms-lab{position:absolute;left:108px;font-size:30px}.ms-myth{position:absolute;left:100px;right:110px;top:420px;font-size:112px;color:var(--ink)}
        .ms-x{position:absolute;left:-10px;right:-10px;top:50%;height:12px;background:var(--accent);transform-origin:0 50%}
        .ms-truth{position:absolute;left:100px;right:110px;top:900px;font-size:136px;color:var(--accent)}`,
  cssW: `.ms-lab{position:absolute;left:150px;font-size:28px}.ms-myth{position:absolute;left:150px;right:auto;max-width:1620px;top:200px;font-size:92px;color:var(--ink)}
        .ms-x{position:absolute;left:-10px;right:-10px;top:50%;height:10px;background:var(--accent);transform-origin:0 50%}
        .ms-truth{position:absolute;left:150px;right:150px;top:520px;font-size:110px;color:var(--accent)}`,
  build(c, s, st) {
    c.el("div", "ms-lab mono", c.esc(s.mythLab || "NHIỀU NGƯỜI NGHĨ"), st).style.top = (c.L.wide ? 150 : 340) + "px";
    const m = c.el("div", "ms-myth heavy", null, st); c.words(m, s.myth);
    const x1 = c.el("div", "ms-x", null, m), x2 = c.el("div", "ms-x", null, m);
    const tl2 = c.el("div", "ms-lab mono", c.esc(s.truthLab || "THẬT RA"), st); tl2.style.top = (c.L.wide ? 470 : 830) + "px"; tl2.style.color = "var(--accent)";
    const t = c.el("div", "ms-truth heavy", null, st); c.words(t, s.truth);
    return { m, x1, x2, t, tl2 };
  },
  enter(c, h, t0, s) {
    c.reveal(h.m, t0 + .05, { x: -320, y: 0, d: .45 });
    const ts = c.t(s.strikeAt, t0 + 1.5);
    c.tl.set([h.x1, h.x2], { scaleX: 0 }, 0);
    const rr = c.L.wide ? 5 : 12;      // khổ ngang: dòng dài -> gạch thoải hơn
    c.tl.fromTo(h.x1, { scaleX: 0, rotation: -rr }, { scaleX: 1, rotation: -rr, duration: .3, ease: c.E.draw, immediateRender: false }, ts);
    c.tl.fromTo(h.x2, { scaleX: 0, rotation: rr }, { scaleX: 1, rotation: rr, duration: .3, ease: c.E.draw, immediateRender: false }, ts + .15);
    c.tl.to(h.m, { opacity: .55, duration: .3 }, ts + .15);
    const tt = c.t(s.truthAt, ts + .8);
    [h.tl2, h.t].forEach((n) => { c.tl.set(n, { autoAlpha: 0 }, 0); c.tl.set(n, { autoAlpha: 1 }, tt); });
    c.tl.fromTo(h.t, { scale: 1.25, filter: `blur(${c.M.blur}px)` }, { scale: 1, filter: "blur(0px)", duration: c.S(.5), ease: "expo.out", immediateRender: false }, tt);
    c.tl.set(h.t, { filter: "none" }, tt + c.S(.5));
  },
});

/* PROCESS / CYCLE devices (tính vào ngân sách "circle": tối đa 1 / video) */
const HFS_CHI = ["Tý", "Sửu", "Dần", "Mão", "Thìn", "Tỵ", "Ngọ", "Mùi", "Thân", "Dậu", "Tuất", "Hợi"];

// Bánh xe N ô (mặc định 12 chi) nghiêng 3D (lớp ngoài nghiêng, lớp trong xoay), quay về ô đích, làm phẳng rồi vẽ đường nối.
HFS.device("wheel", {
  meta: { purpose: "process", framing: "center-hero", axis: "3D", circle: 1, energy: "M" },
  css: `.wh-stage{position:absolute;left:0;top:250px;width:1080px;height:1200px;perspective:1600px}
        .wh-tilt{position:absolute;left:110px;top:150px;width:860px;height:860px;transform-style:preserve-3d}
        .wh-disc{position:absolute;inset:0}.wh-kick{position:absolute;left:108px;top:300px;font-size:30px;color:var(--accent)}
        .wh-tag{position:absolute;left:100px;top:1290px}`,
  cssW: `.wh-stage{position:absolute;left:0;top:0;width:1120px;height:1080px;perspective:1600px}
        .wh-tilt{position:absolute;left:230px;top:96px;width:740px;height:740px;transform-style:preserve-3d}
        .wh-tilt svg{width:100%;height:100%}
        .wh-disc{position:absolute;inset:0}.wh-kick{position:absolute;left:1060px;top:300px;font-size:28px;color:var(--accent)}
        .wh-tag{position:absolute;left:1060px;top:360px}`,
  build(c, s, st) {
    if (s.kick) c.el("div", "wh-kick mono", c.esc(s.kick), st);
    const labs = s.labels || HFS_CHI, N = labs.length, step = 360 / N;
    const stage = c.el("div", "wh-stage", null, st), tilt = c.el("div", "wh-tilt", null, stage), disc = c.el("div", "wh-disc", null, tilt);
    const svg = c.sv("svg", { width: 860, height: 860, viewBox: "-430 -430 860 860" }, disc);
    const R = 410, r0 = 108, P = (a, r) => [Math.sin(a * Math.PI / 180) * r, -Math.cos(a * Math.PI / 180) * r];
    c.sv("circle", { r: R + 8, style: "fill:none;stroke:var(--ink)", "stroke-width": 4 }, svg);
    const wedges = [], labels = [], nodes = [];
    labs.forEach((lab, i) => {
      const a0 = i * step - step / 2, a1 = i * step + step / 2, [x0, y0] = P(a0, R), [x1, y1] = P(a1, R), [x2, y2] = P(a1, r0), [x3, y3] = P(a0, r0);
      wedges.push(c.sv("path", { d: `M${x0},${y0} A${R},${R} 0 0 1 ${x1},${y1} L${x2},${y2} A${r0},${r0} 0 0 0 ${x3},${y3} Z`,
        style: `fill:${i % 2 ? "var(--ground2)" : "var(--ground)"};stroke:var(--ink)`, "stroke-width": 2 }, svg));
      const [lx, ly] = P(i * step, (R + r0) / 2 + 10), g = c.sv("g", { transform: `translate(${lx},${ly})` }, svg);
      const t = c.sv("text", { "text-anchor": "middle", y: 22, "font-weight": 900, "font-size": N > 12 ? 44 : 62, style: "font-family:var(--font-body);fill:var(--ink)" }, g);
      t.textContent = lab; labels.push({ g, lx, ly, t }); nodes.push(P(i * step, s.linkR || 232));
    });
    c.sv("circle", { r: r0 - 4, style: "fill:var(--ink)" }, svg);
    const lines = (s.links || []).map((pair) => { const [p, q] = pair.map((x) => nodes[labs.indexOf(x)]);
      return c.sv("line", { x1: p[0], y1: p[1], x2: q[0], y2: q[1], style: `stroke:${s.linkTone === "accent" ? "var(--accent)" : "var(--glow)"}`, "stroke-width": 14, "stroke-linecap": "round", opacity: 0 }, svg); });
    const tag = c.el("div", "wh-tag", null, st); c.el("span", "pill", c.esc(s.tag || ""), tag);
    return { tilt, disc, wedges, labels, lines, tag, idx: labs.indexOf(s.target), labs, step };
  },
  enter(c, h, t0, s) {
    const sp = { a: 180 - h.idx * h.step - 900, tilt: 52 }, a1 = 180 - h.idx * h.step - 720;
    const place = () => { gsap.set(h.tilt, { rotationX: sp.tilt }); gsap.set(h.disc, { rotation: sp.a });
      h.labels.forEach((L) => L.g.setAttribute("transform", `translate(${L.lx},${L.ly}) rotate(${-sp.a})`)); };
    place();
    c.tl.fromTo(sp, { a: sp.a, tilt: 52 }, { a: a1, tilt: 52, duration: c.S(2.0), ease: "power4.out", onUpdate: place, immediateRender: false }, t0);
    const tl2 = t0 + c.S(1.7);
    c.tl.set(h.wedges[h.idx], { attr: { style: "fill:var(--accent);stroke:var(--ink)" } }, tl2);
    c.tl.set(h.labels[h.idx].t, { attr: { style: "font-family:var(--font-body);fill:var(--on-accent,#fff)" } }, tl2);
    (s.also || []).forEach((x) => c.tl.set(h.wedges[h.labs.indexOf(x)], { attr: { style: "fill:var(--glow-soft, var(--ground2));stroke:var(--ink)" } }, c.t(s.alsoAt, tl2 + .4)));
    const tf = Math.max(tl2 + .3, c.t(s.linkAt, tl2 + .6));
    c.tl.to(sp, { tilt: 18, duration: c.S(.7), ease: c.E.move, onUpdate: place }, tf - .5);
    h.lines.forEach((ln, k) => { const len = Math.hypot(ln.x2.baseVal.value - ln.x1.baseVal.value, ln.y2.baseVal.value - ln.y1.baseVal.value);
      ln.setAttribute("stroke-dasharray", len); c.tl.set(ln, { attr: { "stroke-dashoffset": len }, opacity: 1 }, tf);
      c.tl.to(ln, { attr: { "stroke-dashoffset": 0 }, duration: c.S(.4), ease: c.E.draw }, tf + k * .28); });
    c.reveal(h.tag, c.t(s.tagAt, tf + .3), { x: -60, y: 0, d: .45 });
  },
});

// Chu trình tự vẽ: các nút trên vòng/ngũ giác, mỗi mũi tên vẽ theo mốc lời, nút đích bật khi mũi tên tới.
HFS.device("cycle_draw", {
  meta: { purpose: "process", framing: "center-hero", axis: "draw", circle: 1, energy: "M" },
  css: `.cy-kick{position:absolute;left:108px;top:300px;font-size:30px;color:var(--accent)}
        .cy-svg{position:absolute;left:90px;top:400px}`,
  cssW: `.cy-kick{position:absolute;left:1060px;top:300px;font-size:28px;color:var(--accent)}
        .cy-svg{position:absolute;left:230px;top:100px;width:740px;height:740px}`,
  build(c, s, st) {
    if (s.kick) c.el("div", "cy-kick mono", c.esc(s.kick), st);
    const N = s.nodes.length, R = 330, cx = 450, cy = 450;
    const svg = c.sv("svg", { width: 900, height: 900, viewBox: "0 0 900 900", class: "cy-svg" }, st);
    const pos = s.nodes.map((_, i) => { const a = (i / N) * Math.PI * 2 - Math.PI / 2; return [cx + Math.cos(a) * R, cy + Math.sin(a) * R]; });
    const edges = (s.edges || []).map((e) => { const a = pos[s.nodes.findIndex((n) => n.id === e.from)], b = pos[s.nodes.findIndex((n) => n.id === e.to)];
      const mx = (a[0] + b[0]) / 2, my = (a[1] + b[1]) / 2, k = e.kind === "inner" ? 0 : .35;
      const qx = mx + (mx - cx) * k, qy = my + (my - cy) * k, sh = 92 / Math.hypot(b[0] - a[0], b[1] - a[1]);
      const ax = a[0] + (qx - a[0]) * sh * 1.2, ay = a[1] + (qy - a[1]) * sh * 1.2, bx = b[0] + (qx - b[0]) * sh * 1.2, by = b[1] + (qy - b[1]) * sh * 1.2;
      return { e, p: c.sv("path", { d: `M${ax},${ay} Q${qx},${qy} ${bx},${by}`, style: `fill:none;stroke:${e.kind === "inner" ? "var(--accent)" : "var(--ink)"}`,
        "stroke-width": e.kind === "inner" ? 6 : 9, "stroke-linecap": "round", "stroke-dasharray": e.kind === "inner" ? "" : "", opacity: 0 }, svg), to: b }; });
    const nodes = s.nodes.map((n, i) => { const g0 = c.sv("g", { transform: `translate(${pos[i][0]},${pos[i][1]})` }, svg), g = c.sv("g", {}, g0);
      c.sv("circle", { r: 88, style: `fill:${n.tone === "accent" ? "var(--accent)" : "var(--ground2)"};stroke:var(--ink)`, "stroke-width": 4 }, g);
      const t = c.sv("text", { "text-anchor": "middle", y: 20, "font-weight": 900, "font-size": n.label.length > 4 ? 46 : 58,
        style: `font-family:var(--font-body);fill:${n.tone === "accent" ? "var(--on-accent,#fff)" : "var(--ink)"}` }, g); t.textContent = n.label; return g; });
    return { edges, nodes };
  },
  enter(c, h, t0, s) {
    h.nodes.forEach((g, i) => { const at = c.t(s.nodes[i].at, t0 + .1 + i * .08);
      c.tl.set(g, { autoAlpha: 0 }, 0); c.tl.set(g, { autoAlpha: 1 }, at);
      c.tl.fromTo(g, { scale: .6, transformOrigin: "50% 50%" }, { scale: 1, duration: c.S(.35), ease: c.E.entry, immediateRender: false }, at); });
    h.edges.forEach((ed) => c.draw(ed.p, c.t(ed.e.at, t0 + 1), .55));
  },
});

/* HOOK devices -- khung 0 phải đủ nghĩa (câu trả lời đã hiện), phát triển theo mốc giọng sau đó. */
HFS.device("hook_poster", {
  meta: { purpose: "hook", framing: "edge-band", axis: "static", circle: 0, energy: "H" },
  css: `.hp-num{position:absolute;left:96px;top:300px;font-size:380px;line-height:1;color:var(--accent);transform:rotate(-6deg);transform-origin:0 100%;
          text-shadow:6px 6px 0 var(--accent2),12px 12px 0 var(--shadow, rgba(0,0,0,.15));white-space:nowrap}
        .hp-kick{position:absolute;left:108px;top:760px;font-size:32px;color:var(--ink)}
        .hp-big{position:absolute;left:100px;right:110px;top:810px;font-size:150px;color:var(--accent)}`,
  cssW: `.hp-num{position:absolute;left:130px;top:150px;font-size:360px;line-height:1;color:var(--accent);transform:rotate(-6deg);transform-origin:0 100%;
          text-shadow:6px 6px 0 var(--accent2),12px 12px 0 var(--shadow, rgba(0,0,0,.15));white-space:nowrap}
        .hp-kick{position:absolute;left:150px;top:572px;font-size:30px;color:var(--ink)}
        .hp-big{position:absolute;left:142px;right:150px;top:618px;font-size:150px;color:var(--accent)}`,
  build(c, s, st) {
    st.setAttribute("data-layout-allow-overlap", "");          // số nghiêng đè lên dòng dưới là chủ ý (poster)
    c.el("div", "hp-num disp", c.esc(s.num || ""), st);
    c.el("div", "hp-kick mono", c.esc(s.kick || ""), st);
    const big = c.el("div", "hp-big heavy", null, st);
    if (c.L.wide) { const n = String(s.big || "").replace(/\*\*/g, "").length;   // khổ ngang: giữ 1 dòng trên dải phụ đề
      big.style.fontSize = (n > 30 ? 84 : n > 22 ? 104 : n > 16 ? 124 : 150) + "px"; }
    return { ws: c.words(big, s.big) };
  },
  enter(c, h, t0, s) { const k = s.markWord != null ? s.markWord : h.ws.length - 1; c.underline(h.ws[k].wd, c.t(s.markAt, t0 + 1.2)); },
});

/* nhiều nhóm chữ đập vào theo mốc, mỗi nhóm một trục khác nhau (Z-slam -> X-snap -> Y-rise); nhóm 1 hiện sẵn ở khung 0 */
HFS.device("hook_slam", {
  meta: { purpose: "hook", framing: "edge-band", axis: "Z", circle: 0, energy: "H" },
  css: `.hs-wrap{position:absolute;left:100px;right:110px;top:330px;display:flex;flex-direction:column;gap:26px}
        .hs-g{position:relative;font-size:128px;line-height:1.14;color:var(--ink)} .hs-g.big{font-size:176px;color:var(--accent)}
        .hs-kick{position:absolute;left:108px;top:270px;font-size:30px;color:var(--accent)}`,
  cssW: `.hs-wrap{position:absolute;left:150px;right:150px;top:200px;display:flex;flex-direction:column;gap:18px}
        .hs-g{position:relative;font-size:96px;line-height:1.14;color:var(--ink)} .hs-g.big{font-size:150px;color:var(--accent)}
        .hs-kick{position:absolute;left:152px;top:150px;font-size:28px;color:var(--accent)}`,
  build(c, s, st) {
    if (s.kick) c.el("div", "hs-kick mono", c.esc(s.kick), st);
    const w = c.el("div", "hs-wrap", null, st);
    return { gs: s.groups.map((g) => { const d = c.el("div", "hs-g heavy" + (g.big ? " big disp" : ""), null, w); c.words(d, g.text); return d; }) };
  },
  enter(c, h, t0, s) {
    const moves = [{ scale: 1.5, filter: `blur(${c.M.blur}px)` }, { x: -320 }, { y: 90, rotation: 4 }];
    if (s.allAtStart) { h.gs.forEach((g, i) => { if (!i) return; const t = c.t(s.groups[i].at, t0 + i);
        c.tl.fromTo(g, { scale: 1.12 }, { scale: 1, duration: c.S(.45), ease: c.E.entry, immediateRender: false }, t); });
      c.underline(h.gs[h.gs.length - 1], c.t(s.markAt, t0 + 2)); return; }
    h.gs.forEach((g, i) => { if (i === 0) return;        // nhóm 1 đứng sẵn ở khung 0
      const t = c.t(s.groups[i].at, t0 + i), mv = moves[i % moves.length];
      c.tl.set(g, { autoAlpha: 0 }, 0); c.tl.set(g, { autoAlpha: 1 }, t);
      c.tl.fromTo(g, Object.assign({ x: 0, y: 0, scale: 1, rotation: 0, filter: "blur(0px)" }, mv),
        { x: 0, y: 0, scale: 1, rotation: 0, filter: "blur(0px)", duration: c.S(.5), ease: c.E.entry, immediateRender: false }, t);
      c.tl.set(g, { filter: "none" }, t + c.S(.5)); });
    const last = h.gs[h.gs.length - 1];
    c.underline(last, c.t(s.markAt, t0 + 2));
  },
});

/* MARK / EVIDENCE devices */
// Chữ lớn + chữ Hán mờ + các dấu son đóng theo mốc lời (cảnh báo, phán định theo truyền thống).
HFS.device("stamp", {
  meta: { purpose: "statement", framing: "edge-band", axis: "X", circle: 0, energy: "H" },
  css: `.st-han{position:absolute;left:0;right:0;top:320px;text-align:center;font-size:880px;line-height:1;color:var(--ghost-accent, rgba(195,47,39,.08));font-family:var(--font-cjk, serif)}
        .st-kick{position:absolute;left:108px;top:330px;font-size:32px;color:var(--accent)}
        .st-big{position:absolute;left:96px;top:400px;font-size:320px;line-height:1.05;white-space:nowrap}`,
