// Chữ khổng lồ làm cửa sổ: fill = "rain" (mưa vẽ bằng code), "image" (ảnh, có xử lý màu), "stripes".
HFS.device("window", {
  meta: { purpose: "statement", framing: "center-hero", axis: "in-glyph", circle: 0, energy: "M" },
