        const meta = c.el("div", "tc-meta", c.esc(r.meta), wrap);
        meta.style.left = wide ? "720px" : "450px";
        meta.style.right = wide ? "220px" : "120px";
        meta.style.top = (y + (wide ? 78 : 96)) + "px";
        meta.style.fontSize = (wide ? 24 : 32) + "px";
      }
    });
    const note = c.el("div", "tc-note", c.esc(s.note || ""), wrap);
    note.style.top = wide ? "760px" : "1288px";
    return { rule };
  },
  enter(c, h, t0) {
    if (h.rule) c.draw(h.rule, Math.max(0, t0 + 0.25), 0.55);
  },
});

/* TIME devices */
// Lịch bloc xé: trang lật (rotationX) theo mốc, trang cuối giữ lại + dấu son. Ẩn trang bằng autoAlpha (an toàn khi tua ngược).
HFS.device("calendar", {
  meta: { purpose: "time", framing: "card-on-field", axis: "3D", circle: 0, energy: "M" },
  css: `.cl-stage{position:absolute;left:0;top:250px;width:1080px;height:1220px;perspective:1500px}
