      (c.L.wide ? [140, 434] : [180, 570]).forEach((x) => { c.el("div", "cl-ring", null, pg).style.left = x + "px"; }); pages.unshift(pg); });
    const sx = s.stampX || (c.L.wide ? 990 : 300), sy = s.stampY || (c.L.wide ? 600 : 1180);
