    (s.flips || []).forEach((f, k) => { const tf = c.t(f, t0 + 1 + k);
      c.tl.fromTo(h.pages[k], { rotationX: 0, y: 0 }, { rotationX: 112, y: -40, duration: .5, ease: "power2.in", immediateRender: false }, tf - .15);
